def solve():
    N = 61
    # C[k] = number of (a,b) such that a^2 + b^2 \equiv k (mod N)
    C = [0] * N
    for a in range(N):
        for b in range(N):
            C[(a**2 + b**2) % N] += 1

    # D[m] = number of (c,d) such that c^3 - d^3 \equiv m (mod N)
    D = [0] * N
    for c in range(N):
        for d in range(N):
            D[(c**3 - d**3) % N] += 1

    total = 0
    for k in range(N):
        # we want k + m \equiv 0 (mod N) => m \equiv -k (mod N)
        m = (N - k) % N
        total += C[k] * D[m]
    return total

print(solve())

